import numpy as np

bureau_probs = {
    'S1': [0.08, 0.06, 0.00, 0.26, 0.44, 0.16],
    'S2': [0.02, 0.02, 0.02, 0.30, 0.44, 0.20],
    'S3': [0.08, 0.08, 0.18, 0.32, 0.22, 0.12],
    'S4': [0.10, 0.20, 0.46, 0.16, 0.04, 0.04],
    'S5': [0.04, 0.20, 0.60, 0.08, 0.00, 0.08],
    'S6': [0.22, 0.42, 0.22, 0.06, 0.00, 0.08],
}

income_probs = {
    'S1': [0.00, 0.00, 0.06, 0.22, 0.56, 0.16],
    'S2': [0.02, 0.02, 0.08, 0.44, 0.38, 0.06],
    'S3': [0.00, 0.16, 0.52, 0.30, 0.02, 0.00],
    'S4': [0.14, 0.54, 0.26, 0.06, 0.00, 0.00],
    'S5': [0.10, 0.60, 0.24, 0.04, 0.02, 0.00],
    'S6': [0.10, 0.66, 0.20, 0.04, 0.00, 0.00],
}

bank_probs = {
    'S1': [0.04, 0.02, 0.02, 0.26, 0.48, 0.18],
    'S2': [0.16, 0.02, 0.18, 0.34, 0.14, 0.16],
    'S3': [0.10, 0.08, 0.20, 0.36, 0.14, 0.12],
    'S4': [0.12, 0.18, 0.38, 0.14, 0.08, 0.10],
    'S5': [0.40, 0.34, 0.14, 0.04, 0.02, 0.06],
    'S6': [0.66, 0.22, 0.04, 0.00, 0.00, 0.08],
}

check_probs = {'bureau': bureau_probs, 'income': income_probs, 'bank': bank_probs}
segments = ['S1','S2','S3','S4','S5','S6']
PD = {'S1':0.02,'S2':0.05,'S3':0.12,'S4':0.30,'S5':0.60,'S6':0.90}

def update_posterior(prior, check, band):
    likelihoods = np.array([check_probs[check][s][band] for s in segments])
    prior_arr = np.array([prior[s] for s in segments])
    posterior = likelihoods * prior_arr
    if posterior.sum() == 0:
        return prior
    posterior = posterior / posterior.sum()
    return {s: posterior[i] for i, s in enumerate(segments)}

def expected_pd(posterior):
    return sum(posterior[s] * PD[s] for s in segments)

def ev_approve(posterior):
    epd = expected_pd(posterior)
    return (1 - epd) * 1000 - epd * 16000

def band_prob(prior, check, band):
    return sum(check_probs[check][s][band] * prior[s] for s in segments)

prior1 = {"S1":0.05,"S2":0.34,"S3":0.32,"S4":0.06,"S5":0.15,"S6":0.08}

print("=== Detailed analysis for Applicant 1 ===")
print(f"Prior E[PD]: {expected_pd(prior1):.4f}")
print(f"Prior EV approve: {ev_approve(prior1):.2f}")

for check in ['income', 'bureau', 'bank']:
