            ev = max(0, ev_approve(post))
            total_ev += p * ev
            print(f"  Band {band}: prob={p:.4f}, post_E[PD]={expected_pd(post):.4f}, EV_approve={ev_approve(post):.2f}, decision={'APPROVE' if ev_approve(post)>0 else 'DECLINE'}")
    print(f"  Expected EV after check (before cost): {total_ev:.2f}")
    print(f"  Net VOI: {total_ev - 20:.2f}")

# Let's also check applicant 2 which had positive VOI
prior2 = {"S1":0.19,"S2":0.17,"S3":0.05,"S4":0.29,"S5":0.14,"S6":0.16}
print("\n\n=== Detailed analysis for Applicant 2 ===")
print(f"Prior E[PD]: {expected_pd(prior2):.4f}")
print(f"Prior EV approve: {ev_approve(prior2):.2f}")

for check in ['income', 'bureau', 'bank']:
