    for band in range(6):
        p = band_prob(prior2, check, band)
        if p > 0:
            post = update_posterior(prior2, check, band)
            ev = max(0, ev_approve(post))
            total_ev += p * ev
            print(f"  Band {band}: prob={p:.4f}, post_E[PD]={expected_pd(post):.4f}, EV_approve={ev_approve(post):.2f}, decision={'APPROVE' if ev_approve(post)>0 else 'DECLINE'}")
